    @Test
    public void saveKuraChainsTest() throws KuraException, IOException {
        setUpMock();
        Set<LocalRule> localRules = new LinkedHashSet<>();
        localRules.add(new LocalRule(
                5400,
                "tcp",
                new NetworkPair<>((IP4Address) IPAddress.parseHostAddress("0.0.0.0"), (short) 0),
                "eth0",
                null,
                "00:11:22:33:44:55:66",
                "10100:10200"));

        Set<PortForwardRule> portForwardRules = new LinkedHashSet<>();
        PortForwardRule portForwardRule = new PortForwardRule()
                .inboundIface("eth0")
                .outboundIface("eth1")
                .address("172.16.0.1")
                .addressMask(32)
                .protocol("tcp")
                .inPort(3040)
                .outPort(4050)
                .masquerade(true)
                .permittedNetwork("172.16.0.100")
                .permittedNetworkMask(32)
                .permittedMAC("00:11:22:33:44:55:66")
                .sourcePortRange("10100:10200");
        portForwardRules.add(portForwardRule);

        Set<NATRule> autoNatRules = new LinkedHashSet<>();
        autoNatRules.add(new NATRule("eth2", "eth3", true, RuleType.GENERIC));

        Set<NATRule> natRules = new LinkedHashSet<>();
        natRules.add(
                new NATRule("eth4", "eth5", "tcp", "172.16.0.1/24", "172.16.0.2/24", true, RuleType.IP_FORWARDING));

        IptablesConfig iptablesConfig =
                new IsolatedIptablesConfig(localRules, portForwardRules, autoNatRules, natRules, true, executorServiceMock);

        iptablesConfig.saveKuraChains();

        AtomicBoolean isLocalRulePresent = new AtomicBoolean(false);
        AtomicBoolean[] isPortForwardRulePresent = {
            new AtomicBoolean(false), new AtomicBoolean(false), new AtomicBoolean(false), new AtomicBoolean(false)
        };
        AtomicBoolean[] isAutoNatRulePresent = {
            new AtomicBoolean(false), new AtomicBoolean(false), new AtomicBoolean(false)
        };
        AtomicBoolean[] isNatRulePresent = {new AtomicBoolean(false), new AtomicBoolean(false), new AtomicBoolean(false)
        };
        try (Stream<String> lines = Files.lines(Paths.get(iptablesConfig.getFirewallConfigFileName()))) {
            lines.forEach(line -> {
                line = line.trim();
                switch (line) {
                    case "-A input-kura -p tcp -s 0.0.0.0/0 -i eth0 -m mac --mac-source 00:11:22:33:44:55:66 --sport 10100:10200 --dport 5400 -j ACCEPT":
                        isLocalRulePresent.set(true);
                        break;
                    case "-A forward-kura-pf -s 172.16.0.100/32 -d 172.16.0.1/32 -i eth0 -o eth1 -p tcp -m tcp -m mac --mac-source 00:11:22:33:44:55:66 --sport 10100:10200 -j ACCEPT":
                        isPortForwardRulePresent[0].set(true);
                        break;
                    case "-A forward-kura-pf -s 172.16.0.1/32 -i eth1 -o eth0 -p tcp -m state --state RELATED,ESTABLISHED -j ACCEPT":
                        isPortForwardRulePresent[1].set(true);
                        break;
                    case "-A prerouting-kura-pf -s 172.16.0.100/32 -i eth0 -p tcp -m mac --mac-source 00:11:22:33:44:55:66 -m tcp --sport 10100:10200 --dport 3040 -j DNAT --to-destination 172.16.0.1:4050":
                        isPortForwardRulePresent[2].set(true);
                        break;
                    case "-A postrouting-kura-pf -s 172.16.0.100/32 -d 172.16.0.1/32 -o eth1 -p tcp -j MASQUERADE":
                        isPortForwardRulePresent[3].set(true);
                        break;
                    case "-A forward-kura -i eth2 -o eth3 -j ACCEPT":
                        isAutoNatRulePresent[0].set(true);
                        break;
                    case "-A forward-kura -i eth3 -o eth2 -m state --state RELATED,ESTABLISHED -j ACCEPT":
                        isAutoNatRulePresent[1].set(true);
                        break;
                    case "-A postrouting-kura -o eth3 -j MASQUERADE":
                        isAutoNatRulePresent[2].set(true);
                        break;
                    case "-A postrouting-kura-ipf -s 172.16.0.1/24 -d 172.16.0.2/24 -o eth5 -p tcp -j MASQUERADE":
                        isNatRulePresent[0].set(true);
                        break;
                    case "-A forward-kura-ipf -s 172.16.0.1/24 -d 172.16.0.2/24 -i eth4 -o eth5 -p tcp -m tcp -j ACCEPT":
                        isNatRulePresent[1].set(true);
                        break;
                    case "-A forward-kura-ipf -s 172.16.0.2/24 -i eth5 -o eth4 -p tcp -m state --state RELATED,ESTABLISHED -j ACCEPT":
                        isNatRulePresent[2].set(true);
                        break;
                }
            });
        } catch (IOException e) {
            throw new KuraIOException(e, "save() :: failed to save rules on file");
        }
        assertTrue(isLocalRulePresent.get());
        assertTrue(isPortForwardRulePresent[0].get()
                && isPortForwardRulePresent[1].get()
                && isPortForwardRulePresent[2].get()
                && isPortForwardRulePresent[3].get());
        assertTrue(isAutoNatRulePresent[0].get() && isAutoNatRulePresent[1].get() && isAutoNatRulePresent[2].get());
        assertTrue(isNatRulePresent[0].get() && isNatRulePresent[1].get() && isNatRulePresent[2].get());

        File configFile = new File(iptablesConfig.getFirewallConfigTmpFileName());
        Files.deleteIfExists(configFile.toPath());
    }

