    @Test
    public void testSaveKuraChainsWithAdditionalRules() throws KuraException, IOException {
        setUpMock();

        Set<String> additionalFilterRules = new LinkedHashSet<>();
        additionalFilterRules.add("-A input-kura -p tcp --dport 8080 -j ACCEPT");
        additionalFilterRules.add("-A input-kura -p tcp --dport 9090 -j ACCEPT");

        Set<String> additionalNatRules = new LinkedHashSet<>();
        additionalNatRules.add("-A postrouting-kura -o eth2 -j MASQUERADE");

        Set<String> additionalMangleRules = new LinkedHashSet<>();
        additionalMangleRules.add("-A prerouting-kura -p tcp --dport 80 -j MARK --set-mark 1");

        IptablesConfig config = new IsolatedIptablesConfig(executorServiceMock);
        config.setAdditionalFilterRules(additionalFilterRules);
        config.setAdditionalNatRules(additionalNatRules);
        config.setAdditionalMangleRules(additionalMangleRules);

        config.saveKuraChains();

        // Verify additional rules are written to the configuration
        File tempFile = new File(config.getFirewallConfigFileName());
        assertTrue(tempFile.isFile());
        {
            try (Stream<String> lines = Files.lines(tempFile.toPath())) {
                AtomicBoolean foundFilterRule = new AtomicBoolean(false);
                AtomicBoolean foundNatRule = new AtomicBoolean(false);
                AtomicBoolean foundMangleRule = new AtomicBoolean(false);

                lines.forEach(line -> {
                    if (line.contains("-A input-kura -p tcp --dport 8080 -j ACCEPT")) {
                        foundFilterRule.set(true);
                    }
                    if (line.contains("-A postrouting-kura -o eth2 -j MASQUERADE")) {
                        foundNatRule.set(true);
                    }
                    if (line.contains("-A prerouting-kura -p tcp --dport 80 -j MARK --set-mark 1")) {
                        foundMangleRule.set(true);
                    }
                });

                assertTrue(foundFilterRule.get(), "Additional filter rule should be present");
                assertTrue(foundNatRule.get(), "Additional NAT rule should be present");
                assertTrue(foundMangleRule.get(), "Additional mangle rule should be present");
            }
            Files.deleteIfExists(tempFile.toPath());
        }
    }

    @Test
    public void testSaveKuraChainsWithDisallowedIcmp() throws KuraException, IOException {
        setUpMock();
        IptablesConfig config = new IsolatedIptablesConfig(executorServiceMock);
        config.setAllowIcmp(false);

        config.saveKuraChains();

        // Preserve this fork's explicit IPv4 echo request/reply DROP rules.
        File tempFile = new File(config.getFirewallConfigFileName());
        assertTrue(tempFile.isFile());
        {
            try (Stream<String> lines = Files.lines(tempFile.toPath())) {
                java.util.List<String> rules = lines.filter(line -> line.contains("-p icmp")).toList();
                assertEquals(2, rules.size());
                assertTrue(rules.stream().allMatch(line -> line.endsWith("-j DROP")));
                assertTrue(rules.stream().anyMatch(line -> line.contains("--icmp-type 8")));
                assertTrue(rules.stream().anyMatch(line -> line.contains("--icmp-type 0")));
            }
            Files.deleteIfExists(tempFile.toPath());
        }
    }

    @Test
    public void testRestoreWithInvalidFileContent() throws KuraException, IOException {
        IptablesConfig config = new IsolatedIptablesConfig() {
            @Override
            public String getFirewallConfigFileName() {
                return getFirewallConfigTmpFileName();
            }
        };

        // Create a file with invalid iptables content
        String invalidContent =
                "*filter\n" + ":INPUT DROP [0:0]\n" + "-A invalid-chain-name-that-causes-parsing-error\n" + "COMMIT\n";

        try (BufferedWriter writer = new BufferedWriter(new FileWriter(config.getFirewallConfigTmpFileName()))) {
            writer.write(invalidContent);
        }

        try {
            // The restore method should not throw an exception for invalid content
            // It should just silently fail to parse invalid rules
            config.restore();

            // Verify that no valid rules were parsed from the invalid content
            assertTrue(config.getLocalRules().isEmpty(), "Local rules should be empty after parsing invalid content");
            assertTrue(config.getPortForwardRules().isEmpty(), "Port forward rules should be empty after parsing invalid content");
            assertTrue(config.getNatRules().isEmpty(), "NAT rules should be empty after parsing invalid content");
            assertTrue(config.getAutoNatRules().isEmpty(), "Auto NAT rules should be empty after parsing invalid content");
        } finally {
            File tempFile = new File(config.getFirewallConfigTmpFileName());
            Files.deleteIfExists(tempFile.toPath());
        }
    }

