    @Test
    public void testProtectedMethods() {
        IptablesConfig config = new IsolatedIptablesConfig() {
            // Override to make protected methods accessible for testing
            @Override
            protected String getIptablesCommand() {
                return super.getIptablesCommand();
            }

            @Override
            protected String[] getAllowIcmp() {
                return super.getAllowIcmp();
            }

            @Override
            protected String[] getNotAllowIcmp() {
                return super.getNotAllowIcmp();
            }
        };

        assertNotNull(config.getIptablesCommand(), "getIptablesCommand should not return null");
        assertNotNull(config.getAllowIcmp(), "getAllowIcmp should not return null");
        assertNotNull(config.getNotAllowIcmp(), "getNotAllowIcmp should not return null");

        assertTrue(config.getAllowIcmp().length > 0, "getAllowIcmp should return non-empty array");
        // Local IPv4 policy retains explicit echo request/reply DROP rules.
        assertEquals(2, config.getNotAllowIcmp().length, "This fork keeps explicit IPv4 ICMP DROP rules");
    }

    @Test
    public void testSaveKuraChainsFileMoving() throws KuraException, IOException {
        setUpMock();

        // Create a temporary config that we can control file paths for
        IptablesConfig config = new IsolatedIptablesConfig(executorServiceMock) {
            private String tempFileName =
                    directory.resolve("move.tmp").toString();
            private String configFileName =
                    directory.resolve("move.conf").toString();

            @Override
            public String getFirewallConfigTmpFileName() {
                return tempFileName;
            }

            @Override
            public String getFirewallConfigFileName() {
                return configFileName;
            }
        };

        config.saveKuraChains();

        // Verify the final config file was created (temp file was moved)
        File finalConfigFile = new File(config.getFirewallConfigFileName());
        assertTrue(finalConfigFile.exists(), "Final config file should exist");

        // Verify temp file was moved (no longer exists)
        File tempFile = new File(config.getFirewallConfigTmpFileName());
        assertFalse(tempFile.exists(), "Temp file should not exist after move");

        // Clean up
        Files.deleteIfExists(finalConfigFile.toPath());
    }

